  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeEnergyField() {
  static bool inited = false;
  static unsigned long lastUs = 0;
  static float x = 0.0f, y = 0.0f;
  static float vx = 0.0f, vy = 0.0f;

  if (enteredMode == MODE_ENERGY_FIELD) {
    enteredMode = -1;
    inited = false;
    x = 0.0f; y = 0.0f; vx = 0.0f; vy = 0.0f;
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) {
    x = rand01() * 2.0f - 1.0f;
    y = rand01() * 2.0f - 1.0f;
    vx = 0.0f;
    vy = 0.0f;
  }

  unsigned long nowUs = micros();
  if (!inited) {
    lastUs = nowUs;
    inited = true;
  }
  float dt = (float)(nowUs - lastUs) * 1e-6f;
  lastUs = nowUs;
  if (dt > 0.03f) dt = 0.03f;

  const float ax1 = -0.75f, ay1 = -0.15f;
  const float ax2 =  0.70f, ay2 = -0.55f;
  const float ax3 =  0.10f, ay3 =  0.85f;

  float p3 = pot3f();
  float attract = lerpf(0.2f, 5.0f, (float)ctrl2Val / 1023.0f);
  float energy  = lerpf(0.0f, 1.5f, (float)ctrl1Val / 1023.0f);

  float dx1 = ax1 - x, dy1 = ay1 - y;
  float dx2 = ax2 - x, dy2 = ay2 - y;
  float dx3 = ax3 - x, dy3 = ay3 - y;
  float r1 = dx1*dx1 + dy1*dy1 + 0.05f;
  float r2 = dx2*dx2 + dy2*dy2 + 0.05f;
  float r3 = dx3*dx3 + dy3*dy3 + 0.05f;

  float fx = 0.0f, fy = 0.0f;
  fx += attract * dx1 / r1; fy += attract * dy1 / r1;
  fx += attract * dx2 / r2; fy += attract * dy2 / r2;
  fx += attract * dx3 / r3; fy += attract * dy3 / r3;
  fx += (rand01() - 0.5f) * energy * lerpf(0.25f, 2.0f, p3);
  fy += (rand01() - 0.5f) * energy * lerpf(0.25f, 2.0f, p3);

  vx += fx * dt;
  vy += fy * dt;
  float drag = lerpf(0.45f, 3.4f, p3);
  vx *= (1.0f - drag * dt);
  vy *= (1.0f - drag * dt);

  x += vx * dt;
  y += vy * dt;

  if (x < -1.0f) { x = -1.0f; vx *= -0.7f; }
  if (x >  1.0f) { x =  1.0f; vx *= -0.7f; }
  if (y < -1.0f) { y = -1.0f; vy *= -0.7f; }
  if (y >  1.0f) { y =  1.0f; vy *= -0.7f; }

  setOutA(bipolarTo12(x));
  setOutB(bipolarTo12(y));

  float hotRadius = lerpf(0.035f, 0.16f, p3);
  bool hot = (r1 < hotRadius) || (r2 < hotRadius) || (r3 < hotRadius);
  digitalWrite(GATEOUT, hot ? HIGH : LOW);
}

mo_binary_bloom:
enum MotionMode {
  MODE_AD_ENVELOPE = 0,
  MODE_SLEW_FUNCTION,
  MODE_PENDULUM,
  MODE_RADIOACTIVE_GEIGER,
  MODE_SWARM,
  MODE_NEURAL_GHOST,
  MODE_PHASE_FORGE,
  MODE_VECTOR_DRIFT,
  MODE_ENERGY_FIELD,
  MODE_BINARY_BLOOM,
  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeBinaryBloom(unsigned long t) {
  static uint16_t pattern = 0x00F3;
  static unsigned long lastTick = 0;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_BINARY_BLOOM) {
    enteredMode = -1;
    pattern = (uint16_t)random(1, 65535);
    lastTick = t;
    gOn = false;
    setOutA(0);
    setOutB(0);
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) pattern = (uint16_t)random(1, 65535);

  float p3 = pot3f();
  unsigned long tickMs = (unsigned long)lerpf(220.0f, 22.0f, p3);

  if ((unsigned long)(t - lastTick) >= tickMs) {
    lastTick = t;
    uint8_t popBefore = popcount16(pattern);
    uint16_t newP = 0;
    uint8_t birthBias = (uint8_t)map(ctrl1Val, 0, 1023, 0, 255);
    uint8_t decayBias = (uint8_t)map(ctrl2Val, 0, 1023, 0, 255);
    uint8_t mutation = (uint8_t)lerpf(0.0f, 55.0f, p3);

    for (uint8_t i = 0; i < 16; i++) {
      uint8_t l = (i == 0) ? 15 : (i - 1);
      uint8_t r = (i == 15) ? 0 : (i + 1);
      bool self = (pattern >> i) & 1U;
      uint8_t neigh = (((pattern >> l) & 1U) ? 1 : 0) + (((pattern >> r) & 1U) ? 1 : 0);
      bool nextState = self;

      if (!self) {
        uint16_t threshold = (uint16_t)birthBias + (uint16_t)neigh * 70U;
        if (random(0, 256) < (int)(threshold > 255 ? 255 : threshold)) nextState = true;
      } else {
        int decayTh = (int)decayBias - (int)neigh * 40;
        if (decayTh < 0) decayTh = 0;
        if (random(0, 256) < decayTh) nextState = false;
      }

      if (random(0, 256) < mutation) nextState = !nextState;
      if (nextState) newP |= (uint16_t)(1U << i);
    }

    pattern = newP;
    uint8_t popAfter = popcount16(pattern);
    setOutA((uint16_t)map(popAfter, 0, 16, 0, 4095));
    setOutB(quantize12ByPot3((uint16_t)((pattern & 0x00FFU) * 16U)));

    if (popAfter > popBefore) {
      digitalWrite(GATEOUT, HIGH);
      gStart = t;
      gOn = true;
    }
  }

  if (gOn && (t - gStart >= 8UL)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

mo_chaos_map:
enum MotionMode {
  MODE_AD_ENVELOPE = 0,
  MODE_SLEW_FUNCTION,
  MODE_PENDULUM,
  MODE_RADIOACTIVE_GEIGER,
  MODE_SWARM,
  MODE_NEURAL_GHOST,
  MODE_PHASE_FORGE,
  MODE_VECTOR_DRIFT,
  MODE_ENERGY_FIELD,
  MODE_BINARY_BLOOM,
  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeChaosMap(unsigned long t) {
  static float x = 0.314f;
  static float xPrev = 0.271f;
  static unsigned long lastTick = 0;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_CHAOS_MAP) {
    enteredMode = -1;
    x = 0.314f;
    xPrev = 0.271f;
    lastTick = t;
    gOn = false;
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) {
    x = clampf(rand01(), 0.05f, 0.95f);
    xPrev = clampf(rand01(), 0.05f, 0.95f);
  }

  unsigned long tickMs = (unsigned long)map(ctrl2Val, 0, 1023, 5, 350);
  if ((unsigned long)(t - lastTick) >= tickMs) {
    lastTick = t;
    float r = lerpf(2.8f, 4.0f, (float)ctrl1Val / 1023.0f);
    float thr = lerpf(0.35f, 0.92f, pot3f());

    xPrev = x;
    x = r * x * (1.0f - x);
    x = clampf(x, 0.0f, 1.0f);

    setOutA(unipolarTo12(shapeUniByPot3(x)));
    setOutB(unipolarTo12(shapeUniByPot3(xPrev)));

    if (xPrev < thr && x >= thr) {
      digitalWrite(GATEOUT, HIGH);
      gStart = t;
      gOn = true;
    }
  }

  if (gOn && (t - gStart >= 8UL)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

mo_sample_and_hold_morph:
enum MotionMode {
  MODE_AD_ENVELOPE = 0,
  MODE_SLEW_FUNCTION,
  MODE_PENDULUM,
  MODE_RADIOACTIVE_GEIGER,
  MODE_SWARM,
  MODE_NEURAL_GHOST,
  MODE_PHASE_FORGE,
  MODE_VECTOR_DRIFT,
  MODE_ENERGY_FIELD,
  MODE_BINARY_BLOOM,
  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeSampleHoldMorph(unsigned long t) {
  static uint16_t raw = 0;
  static float smooth = 0.0f;
  static unsigned long lastSample = 0;
  static bool inited = false;
  static unsigned long lastUs = 0;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_SAMPLE_HOLD_MORPH) {
    enteredMode = -1;
    raw = quantize12ByPot3((uint16_t)random(0, 4096));
    smooth = (float)raw;
    lastSample = t;
    inited = false;
    gOn = false;
    setOutA(raw);
    setOutB(raw);
    digitalWrite(GATEOUT, LOW);
  }

  bool sampled = false;

  if (checkReset()) {
    sampled = true;
  } else {
    unsigned long intMs = (unsigned long)map(ctrl1Val, 0, 1023, 30, 1800);
    if ((unsigned long)(t - lastSample) >= intMs) sampled = true;
  }

  if (sampled) {
    lastSample = t;
    uint16_t n = analogRead(RANDOM_SEED_PIN);
    long mix = random(0, 4096) ^ ((long)n << 2) ^ (long)micros();
    raw = quantize12ByPot3((uint16_t)(mix & 0x0FFF));
    digitalWrite(GATEOUT, HIGH);
    gStart = t;
    gOn = true;
  }

  unsigned long nowUs = micros();
  if (!inited) {
    lastUs = nowUs;
    inited = true;
  }
  float dt = (float)(nowUs - lastUs) * 1e-6f;
  lastUs = nowUs;
  if (dt > 0.05f) dt = 0.05f;

  float glide = lerpf(40.0f, 1.0f, (float)ctrl2Val / 1023.0f);
  smooth += ((float)raw - smooth) * (1.0f / glide) * (dt * 120.0f);

  setOutA(raw);
  setOutB(clamp12i((int32_t)smooth));

  if (gOn && (t - gStart >= TRIG_PULSE_MS)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

