int enteredMode=-1;
void handleModeHarmonicStack() {
  static bool inited = false;
  static unsigned long lastUs = 0;
  static float phase = 0.0f;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_HARMONIC_STACK) {
    enteredMode = -1;
    inited = false;
    phase = 0.0f;
    gOn = false;
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) phase = 0.0f;

  unsigned long nowUs = micros();
  if (!inited) {
    lastUs = nowUs;
    inited = true;
  }
  float dt = (float)(nowUs - lastUs) * 1e-6f;
  lastUs = nowUs;
  if (dt > 0.05f) dt = 0.05f;

  float base = lerpf(0.03f, 15.0f, (float)ctrl1Val / 1023.0f);
  float mix = (float)ctrl2Val / 1023.0f;
  float oldPhase = phase;
  phase = fract1(phase + base * dt);
  bool wrapped = (phase < oldPhase);

  float p = 2.0f * PI * phase;
  float s1 = sinf(p);
  float s2 = sinf(2.0f * p);
  float s3 = sinf(3.0f * p);
  float s5 = sinf(5.0f * p);

  float a = (1.00f * s1 + (0.65f + 0.25f * mix) * s2 + (0.30f + 0.50f * mix) * s3) / (1.95f + 0.75f * mix);
  float b = (0.90f * s2 + (0.45f + 0.35f * mix) * s3 + (0.20f + 0.70f * mix) * s5) / (1.55f + 1.05f * mix);

  a = foldBiByPot3(a);
  b = foldBiByPot3(b);

  setOutA(bipolarTo12(a));
  setOutB(bipolarTo12(b));

  unsigned long t = millis();
  if (wrapped) {
    digitalWrite(GATEOUT, HIGH);
    gStart = t;
    gOn = true;
  }
  if (gOn && (t - gStart >= 8UL)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

mo_random_walk_constrain:
enum MotionMode {
  MODE_AD_ENVELOPE = 0,
  MODE_SLEW_FUNCTION,
  MODE_PENDULUM,
  MODE_RADIOACTIVE_GEIGER,
  MODE_SWARM,
  MODE_NEURAL_GHOST,
  MODE_PHASE_FORGE,
  MODE_VECTOR_DRIFT,
  MODE_ENERGY_FIELD,
  MODE_BINARY_BLOOM,
  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeRandomWalkConstrain(unsigned long t) {
  static float x = 0.5f;
  static float v = 0.0f;
  static unsigned long lastTick = 0;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_RANDOM_WALK_CONSTRAIN) {
    enteredMode = -1;
    x = 0.5f;
    v = 0.0f;
    lastTick = t;
    gOn = false;
    setOutA(unipolarTo12(x));
    setOutB(bipolarTo12(v));
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) {
    x = 0.5f;
    v = 0.0f;
  }

  unsigned long tickMs = (unsigned long)map(ctrl1Val, 0, 1023, 15, 300);
  if ((unsigned long)(t - lastTick) >= tickMs) {
    lastTick = t;
    float p3 = pot3f();
    float oldV = v;
    float constrain = lerpf(0.0f, 1.4f, (float)ctrl2Val / 1023.0f);
    float step = lerpf(0.035f, 0.28f, p3);
    float delta = (rand01() * 2.0f - 1.0f) * step;
    float pull = (0.5f - x) * 0.22f * constrain;

    v = delta + pull;
    x += v;

    bool hit = false;
    float bounce = lerpf(0.35f, 1.0f, p3);
    if (x < 0.0f) { x = 0.0f; v = fabsf(v) * bounce; hit = true; }
    if (x > 1.0f) { x = 1.0f; v = -fabsf(v) * bounce; hit = true; }

    bool reversed = ((oldV > 0.0f && v < 0.0f) || (oldV < 0.0f && v > 0.0f));
    setOutA(unipolarTo12(shapeUniByPot3(x)));
    setOutB(bipolarTo12(clampf(v * lerpf(2.0f, 6.0f, p3), -1.0f, 1.0f)));

    if (hit || reversed) {
      digitalWrite(GATEOUT, HIGH);
      gStart = t;
      gOn = true;
    }
  }

  if (gOn && (t - gStart >= 8UL)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

mo_cv_cross_mod:
enum MotionMode {
  MODE_AD_ENVELOPE = 0,
  MODE_SLEW_FUNCTION,
  MODE_PENDULUM,
  MODE_RADIOACTIVE_GEIGER,
  MODE_SWARM,
  MODE_NEURAL_GHOST,
  MODE_PHASE_FORGE,
  MODE_VECTOR_DRIFT,
  MODE_ENERGY_FIELD,
  MODE_BINARY_BLOOM,
  MODE_CHAOS_MAP,
  MODE_SAMPLE_HOLD_MORPH,
  MODE_MIRROR_LFO,
  MODE_HARMONIC_STACK,
  MODE_RANDOM_WALK_CONSTRAIN,
  MODE_CV_CROSS_MOD
};


int enteredMode=-1;
void handleModeCvCrossMod() {
  static bool inited = false;
  static unsigned long lastUs = 0;
  static float p1 = 0.0f, p2 = 0.31f;
  static bool prevNearSync = false;
  static bool gOn = false;
  static unsigned long gStart = 0;

  if (enteredMode == MODE_CV_CROSS_MOD) {
    enteredMode = -1;
    inited = false;
    p1 = 0.0f;
    p2 = 0.31f;
    prevNearSync = false;
    gOn = false;
    digitalWrite(GATEOUT, LOW);
  }

  if (checkReset()) {
    p1 = 0.0f;
    p2 = 0.25f;
  }

  unsigned long nowUs = micros();
  if (!inited) {
    lastUs = nowUs;
    inited = true;
  }
  float dt = (float)(nowUs - lastUs) * 1e-6f;
  lastUs = nowUs;
  if (dt > 0.05f) dt = 0.05f;

  float p3 = pot3f();
  float base = lerpf(0.05f, 18.0f, (float)ctrl1Val / 1023.0f);
  float depth = lerpf(0.0f, 1.2f, (float)ctrl2Val / 1023.0f);

  float y1 = 0.5f + 0.5f * sinf(2.0f * PI * p1);
  float y2 = 0.5f + 0.5f * sinf(2.0f * PI * p2);
  float f1 = base * (1.0f + depth * ((y2 - 0.5f) * 0.9f));
  float f2 = (base * 1.37f) * (1.0f + depth * ((y1 - 0.5f) * 0.9f));

  if (f1 < 0.01f) f1 = 0.01f;
  if (f2 < 0.01f) f2 = 0.01f;

  p1 = fract1(p1 + f1 * dt);
  p2 = fract1(p2 + f2 * dt);

  float sine1 = sinf(2.0f * PI * p1);
  float sine2 = sinf(2.0f * PI * p2);
  float tri1 = tri01(p1) * 2.0f - 1.0f;
  float tri2 = tri01(p2) * 2.0f - 1.0f;
  float wave1 = lerpf(sine1, foldBiByPot3(tri1), p3);
  float wave2 = lerpf(sine2, foldBiByPot3(tri2), p3);

  setOutA(bipolarTo12(wave1));
  setOutB(bipolarTo12(wave2));

  float d = fabsf(p1 - p2);
  if (d > 0.5f) d = 1.0f - d;
  bool nearSync = (d < lerpf(0.008f, 0.055f, p3));

  unsigned long t = millis();
  if (nearSync && !prevNearSync) {
    digitalWrite(GATEOUT, HIGH);
    gStart = t;
    gOn = true;
  }
  prevNearSync = nearSync;

  if (gOn && (t - gStart >= 8UL)) {
    digitalWrite(GATEOUT, LOW);
    gOn = false;
  }
}

cv_sh_glide:
static void modeSHGlide(unsigned long t) {
  static uint16_t target = 2048;
  static uint16_t out2 = 2048;
  static unsigned long lastClk, clkP;
  static unsigned long lastMove;

  if (modeJustChanged) {
    target = 2048;
    out2 = 2048;
    lastClk = 0;
    clkP = 0;
    lastMove = t;
    schClearAll();
    dacSetA(2048);
    dacSetB(2048);
    setGate(false);
  }

  unsigned long now = t;
  unsigned long dt = now - lastMove;
  if (dt > 25) dt = 25;
  lastMove = now;

  uint16_t glide = (uint16_t)map(ctrl2Val, 0, 1023, 0, 450);
  if (glide == 0) {
    out2 = target;
  } else {
    int32_t err = (int32_t)target - (int32_t)out2;
    int32_t step = (err * (int32_t)dt) / (int32_t)glide;

    if (step == 0 && err != 0) {
      step = (err > 0) ? 1 : -1;
    }

    if ((err > 0 && step > err) || (err < 0 && step < err)) {
      step = err;
    }

    out2 = clamp12((int32_t)out2 + step);
  }
  dacSetB(out2);

  if (checkReset()) {
    if (lastClk) clkP = t - lastClk;
    lastClk = t;
    unsigned long pw = pulseWidthFromClock(clkP ? clkP : 40);

    int range = map(ctrl1Val, 0, 1023, 0, 2047);
    int raw = 2048 + (int)random(-range, range + 1);
    if (raw < 0) raw = 0;
    if (raw > 4095) raw = 4095;

    target = quantizeByPot((uint16_t)raw, ctrl3Val);
    dacSetA(target);
    schPulseG(t, 0, pw);
  }

  schService(t);
}

cv_ad_eoc:
static void modeAD_EOC(unsigned long t) {
  static bool env;
  static unsigned long tStart, attMs, decMs;

  if (modeJustChanged) {
    env = false;
    tStart = 0;
    attMs = 50;
    decMs = 200;
    schClearAll();
    dacSetA(0);
    dacSetB(4095);
    setGate(false);
  }

  if (checkReset()) {
    attMs = (unsigned long)mapQuadraticTo(ctrl1Val, 5, 2500);
    decMs = (unsigned long)mapQuadraticTo(ctrl2Val, 5, 2500);
    tStart = t;
    env = true;
    setGate(false);
    dacSetA(0);
    dacSetB(4095);
  }

  if (env) {
    unsigned long el = t - tStart;
    unsigned long total = attMs + decMs;
    uint16_t v = 0;

    if (el <= attMs) {
      uint16_t x = attMs ? (uint16_t)((el * 4095UL) / attMs) : 4095;
      v = shapeProgressByPot(x, ctrl3Val);
    } else if (el <= total) {
      unsigned long de = el - attMs;
      uint16_t x = decMs ? (uint16_t)((de * 4095UL) / decMs) : 4095;
      uint16_t shaped = shapeProgressByPot(x, ctrl3Val);
      v = (uint16_t)(4095 - shaped);
    } else {
      env = false;
      v = 0;
      schPulseG(t, 0, 10);
    }

    dacSetA(v);
    dacSetB((uint16_t)(4095 - v));
  }

  schService(t);
}

